<script module lang="ts">
/**
 * A string drawn as a scannable QR Code symbol (`design/components/qr-code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/qr-code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import {
  QR_QUIET_ZONE,
  devWarning,
  joinSlot,
  qrPath,
  qrSymbol,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/qr-code.module.css'

export type QRCodeSize = NonNullable<QRCodeProps['size']>

export type QRCodeErrorCorrection = NonNullable<QRCodeProps['errorCorrection']>

export interface QRCodeProps {
  /**
   * Damage tolerance: `L` 7%, `M` 15%, `Q` 25%, `H` 30%. More correction means a denser symbol,
   * the worse trade on a screen: displays do not get scuffed, and dense symbols scan worse at
   * arm's length. `M` is the screen default.
   */
  errorCorrection?: 'L' | 'M' | 'Q' | 'H'
  /**
   * The accessible name: what the symbol is *for* ("Authenticator setup code"), never its
   * contents. Required, because the symbol is noise to a reader who cannot scan it.
   */
  label: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * The content, encoded as UTF-8; always controlled, as the symbol is a pure function of it.
   */
  value: string
}
</script>

<script lang="ts">
let { errorCorrection = 'M', label: labelOwn, size = 'md', value }: QRCodeProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const symbol = $derived(qrSymbol(value, errorCorrection))
const extent = $derived(symbol === null ? 0 : symbol.size + QR_QUIET_ZONE * 2)
const ink = $derived(symbol === null ? '' : qrPath(symbol, QR_QUIET_ZONE))
const effect1 = () => {
  devWarning(
    symbol === null,
    `QRCode: \`value\` (${value.length} characters) does not fit a QR symbol at correction level ${errorCorrection}. Nothing was rendered.`,
  )
}
watchEffect(effect1, { watch: () => [symbol, errorCorrection] })
const effect2 = () => {
  devWarning(value === '', 'QRCode: `value` is empty. Nothing was rendered.')
}
watchEffect(effect2, { watch: () => value })
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if symbol !== null && value !== ''
    }<svg
      class={styles.symbol}
      viewBox={`0 0 ${extent} ${extent}`}
      role="img"
      aria-label={label}
      shape-rendering="crispEdges"
      data-size={size}
      data-mode="light"
      data-member="qr-code"
      ><rect class={styles.paper} width={extent} height={extent}></rect
      ><path class={styles.ink} d={ink}></path
    ></svg
  >{/if
}{/if
}{@render joined.end?.()}
